$root = dirname(__DIR__);
$out = [];
$q = function ($v) {
    if ($v === null) {
        return 'NULL';
    }
    if (is_int($v) || is_float($v)) {
        return (string) $v;
    }
    return "'" . str_replace(["\\", "'", "\n", "\r"], ["\\\\", "\\'", "\\n", ''], (string) $v) . "'";
};
$insert = function (string $table, array $rows) use (&$out, $q) {
    if (!$rows) {
        return;
    }
    $cols = array_keys($rows[0]);
    $vals = [];
    foreach ($rows as $r) {
        $vals[] = '(' . implode(', ', array_map($q, array_values($r))) . ')';
    }
    foreach (array_chunk($vals, 50) as $chunk) {
        $out[] = 'INSERT INTO `' . $table . '` (`' . implode('`, `', $cols) . "`) VALUES\n" . implode(",\n", $chunk) . ';';
    }
};
