$pid = 0;
$stockSeed = 7;
$nextStock = function () use (&$stockSeed) {
    $stockSeed = ($stockSeed * 37 + 11) % 97;
    return $stockSeed % 9 === 0 ? 0 : 3 + $stockSeed % 18;
};
$product = function (array $p) use (&$products, &$images, &$variants, &$values, &$attrs, &$inventory, &$vid, &$pid, $catId, $nextStock, $img) {
    $pid++;
    $p += ['sale_price' => null, 'badge' => null, 'is_new' => 0, 'is_bestseller' => 0, 'is_featured' => 0, 'options' => [], 'stock' => 25,
        'fit' => null, 'fabric' => null, 'pattern' => null, 'sleeve_type' => null, 'collar_type' => null, 'waist_type' => null, 'length_type' => null,
        'season' => 'All Season', 'occasion' => null, 'care' => null, 'made_to_order' => 0, 'lead_time_days' => 0, 'is_customizable' => 0,
        'custom_fields' => null, 'customization_fee' => 0, 'brand' => 'Urban Collections', 'attrs' => [], 'weight' => 0.4, 'days_ago' => 30, 'garment' => null, 'urgent' => 1];
    $hasVariants = $p['options'] ? 1 : 0;
    $products[] = [
        'id' => $pid, 'category_id' => $catId[$p['cat']], 'name' => $p['name'], 'slug' => $p['slug'], 'sku' => $p['sku'],
        'short_description' => $p['short'], 'description' => $p['desc'], 'price' => $p['price'], 'sale_price' => $p['sale_price'],
        'cost_price' => round($p['price'] * 0.45), 'has_variants' => $hasVariants, 'track_stock' => 1, 'stock_qty' => $hasVariants ? 0 : $p['stock'],
        'low_stock_threshold' => 3, 'allow_backorder' => 0, 'weight_kg' => $p['weight'], 'brand' => $p['brand'], 'fabric' => $p['fabric'], 'fit' => $p['fit'],
        'pattern' => $p['pattern'], 'sleeve_type' => $p['sleeve_type'], 'collar_type' => $p['collar_type'], 'waist_type' => $p['waist_type'],
        'length_type' => $p['length_type'], 'season' => $p['season'], 'occasion' => $p['occasion'], 'care_instructions' => $p['care'],
        'ready_to_ship' => $p['made_to_order'] ? 0 : 1, 'made_to_order' => $p['made_to_order'], 'lead_time_days' => $p['lead_time_days'],
        'is_customizable' => $p['is_customizable'], 'custom_fields' => $p['custom_fields'], 'customization_fee' => $p['customization_fee'],
        'custom_garment_id' => $p['garment'], 'allow_urgent' => $p['made_to_order'] ? 0 : $p['urgent'],
        'is_featured' => $p['is_featured'], 'is_new' => $p['is_new'], 'is_bestseller' => $p['is_bestseller'], 'badge' => $p['badge'],
        'status' => 'published', 'seo_title' => null, 'meta_description' => $p['short'],
        'published_at' => date('Y-m-d H:i:s', strtotime('-' . $p['days_ago'] . ' days')),
    ];
    $views = ['front', 'back', 'detail', 'lifestyle'];
    foreach ($p['images'] as $i => $im) {
        $images[] = ['product_id' => $pid, 'image' => $img($im), 'alt_text' => $p['name'] . ($i ? ' — ' . $views[$i % 4] . ' view' : ''),
            'caption' => null, 'view_type' => $views[$i % 4], 'sort_order' => $i, 'is_main' => $i === 0 ? 1 : 0];
    }
    if ($hasVariants) {
        $combos = [[]];
        foreach ($p['options'] as $name => $vals) {
            $next = [];
            foreach ($combos as $c) {
                foreach ($vals as $v) {
                    $next[] = $c + [$name => $v];
                }
            }
            $combos = $next;
        }
        foreach ($combos as $i => $combo) {
            $vid++;
            $stock = $nextStock();
            $variants[] = ['id' => $vid, 'product_id' => $pid, 'sku' => $p['sku'] . '-' . strtoupper(implode('-', array_map(fn($v) => preg_replace('/[^A-Za-z0-9]/', '', $v), $combo))),
                'price' => null, 'sale_price' => null, 'stock_qty' => $stock, 'is_active' => 1, 'sort_order' => $i];
            $o = 0;
            foreach ($combo as $name => $v) {
                $values[] = ['variant_id' => $vid, 'option_name' => $name, 'option_value' => $v, 'sort_order' => $o++];
            }
            $inventory[] = ['product_id' => $pid, 'variant_id' => $vid, 'change_qty' => $stock, 'balance_after' => $stock, 'reason' => 'initial', 'note' => 'Opening stock'];
        }
    } else {
        $inventory[] = ['product_id' => $pid, 'variant_id' => null, 'change_qty' => $p['stock'], 'balance_after' => $p['stock'], 'reason' => 'initial', 'note' => 'Opening stock'];
    }
    foreach ($p['attrs'] as $i => [$n, $v]) {
        $attrs[] = ['product_id' => $pid, 'name' => $n, 'value' => $v, 'sort_order' => $i];
    }
    return $pid;
};

