$review = '<p><em>Store owner: review and adapt this page to your actual business practices before launch.</em></p>';
$pages = [
    ['About Urban Collections', 'about-us', 'wide', "Urban Collections is a Pakistani fashion and lifestyle brand for men and women, bringing together modern urban style, traditional wear and bridal classics.",
        '<h2>Style that speaks for you</h2><p>Urban Collections was founded for the modern man who wants to look sharp and feel confident — without overthinking it. We curate and design clothing, footwear and accessories that work across your whole life: the office, the weekend, festive gatherings and the moments that matter.</p><h3>What we stand for</h3><ul><li><strong>Modern design</strong> — contemporary cuts with timeless details.</li><li><strong>Considered quality</strong> — fabrics and finishes chosen to last.</li><li><strong>Versatility</strong> — pieces that pair easily and earn their place in your wardrobe.</li><li><strong>Service</strong> — straightforward delivery, Cash on Delivery and easy exchanges.</li></ul><h3>Find us</h3><p>Follow <a href="https://www.instagram.com/urban_collection11/" target="_blank">@urban_collection11</a> on Instagram and <a href="https://www.facebook.com/profile.php?id=61595441786815" target="_blank">Urban Collections on Facebook</a> for new arrivals and styling inspiration.</p>',
        $img('1441984904996-e0b6ba687e04', 1920)],
    ['Contact Us', 'contact', 'contact', 'Questions about an order, sizing or styling? We are here to help.',
        '<p>Questions about an order, sizing or styling? Send us a message and our team will get back to you as soon as possible.</p>', null],
    ['Size Guide', 'size-guide', 'default', 'Find your perfect fit with the Urban Collections size guide.',
        '<h2>Tops, shirts &amp; jackets</h2><table class="table"><thead><tr><th>Size</th><th>Chest (in)</th><th>Shoulder (in)</th><th>Length (in)</th></tr></thead><tbody><tr><td>S</td><td>36–38</td><td>17</td><td>28</td></tr><tr><td>M</td><td>38–40</td><td>17.5</td><td>29</td></tr><tr><td>L</td><td>40–42</td><td>18</td><td>30</td></tr><tr><td>XL</td><td>42–44</td><td>18.5</td><td>31</td></tr><tr><td>XXL</td><td>44–46</td><td>19</td><td>32</td></tr></tbody></table><h2>Jeans &amp; trousers</h2><table class="table"><thead><tr><th>Waist size</th><th>Waist (in)</th><th>Hip (in)</th></tr></thead><tbody><tr><td>30</td><td>30</td><td>38</td></tr><tr><td>32</td><td>32</td><td>40</td></tr><tr><td>34</td><td>34</td><td>42</td></tr><tr><td>36</td><td>36</td><td>44</td></tr><tr><td>38</td><td>38</td><td>46</td></tr></tbody></table><h2>Footwear</h2><table class="table"><thead><tr><th>EU</th><th>UK</th><th>Foot length (cm)</th></tr></thead><tbody><tr><td>40</td><td>6.5</td><td>25.5</td></tr><tr><td>41</td><td>7</td><td>26</td></tr><tr><td>42</td><td>8</td><td>26.7</td></tr><tr><td>43</td><td>9</td><td>27.5</td></tr><tr><td>44</td><td>9.5</td><td>28.2</td></tr></tbody></table><h3>How to measure</h3><p><strong>Chest:</strong> around the fullest part, under the arms. <strong>Waist:</strong> around your natural waistline. <strong>Foot:</strong> heel to longest toe, standing.</p><p>Between sizes? Choose the larger size for a relaxed fit, or contact us for advice.</p>' . $review, null],
    ["Men's Fashion Guide", 'mens-fashion-guide', 'default', 'Practical style notes for building a versatile modern wardrobe.',
        '<h2>Build a wardrobe that works</h2><p>Start with versatile foundations — a white tee, an Oxford shirt, dark slim jeans, tailored chinos and clean leather sneakers. Add a blazer and a leather jacket, and you have outfits for almost any day.</p><h3>Smart casual, simplified</h3><p>Pair an Oxford shirt with chinos and loafers. Add an unstructured blazer for the evening.</p><h3>Business &amp; formal</h3><p>A well-fitted charcoal or navy suit, a crisp shirt, a knitted tie and polished Oxfords cover meetings, weddings and dinners.</p><h3>Traditional occasions</h3><p>A crisp kurta shalwar with a tailored waistcoat is a timeless choice for Eid, Jummah and family events.</p>', null],
    ['Product Care Guide', 'care-guide', 'default', 'Keep your Urban Collections pieces looking their best for longer.',
        '<h2>Cotton &amp; linen</h2><p>Wash cold with similar colours, inside out. Line dry in shade to protect colour. Iron while slightly damp.</p><h2>Denim</h2><p>Wash sparingly, inside out in cold water. Avoid tumble drying to preserve stretch and colour.</p><h2>Wool &amp; tailoring</h2><p>Dry clean only when needed. Steam to refresh and hang on shaped hangers.</p><h2>Leather</h2><p>Wipe with a soft dry cloth, condition each season and keep away from direct heat.</p><h2>Footwear</h2><p>Use shoe trees, rotate pairs and clean regularly with products suited to the material.</p>', null],
    ['Shipping Policy', 'shipping-policy', 'default', 'Delivery times, charges and coverage.',
        '<h2>Delivery coverage</h2><p>We deliver across Pakistan through trusted courier partners.</p><h2>Delivery charges</h2><p>Delivery charges depend on your city and are shown at checkout before you confirm your order. Free standard delivery applies on orders above the threshold shown on our website.</p><h2>Delivery times</h2><p>Estimated delivery times are shown on each product page and at checkout. Made-to-order and customised items include an additional production time shown on the product.</p><h2>Order tracking</h2><p>Once your order ships you will receive the courier name and tracking number. You can also track your order on our <a href="/track-order">Track Order</a> page.</p>' . $review, null],
    ['Returns & Exchanges', 'returns-and-exchanges', 'default', 'Our returns and exchange policy.',
        '<h2>Exchanges</h2><p>Unworn items with original tags and packaging can be exchanged for a different size or colour within 7 days of delivery, subject to availability.</p><h2>Returns</h2><p>If you receive a damaged or incorrect item, contact us within 48 hours of delivery with photos and your order number and we will make it right.</p><h2>Non-returnable items</h2><p>Customised, made-to-measure and personalised items, perfumes and items marked final sale cannot be returned unless faulty.</p><h2>How to request</h2><p>Contact us with your order number via the <a href="/contact">contact page</a>.</p>' . $review, null],
    ['Privacy Policy', 'privacy-policy', 'default', 'How we collect, use and protect your information.',
        '<h2>Information we collect</h2><p>When you place an order or create an account we collect your name, contact details and delivery address. Payments made online are processed by our payment providers on their secure pages — we never receive or store your full card number or security code.</p><h2>How we use it</h2><p>To process and deliver your orders, provide customer support and, if you opt in, send you marketing emails. You can unsubscribe at any time.</p><h2>Sharing</h2><p>We share only what is necessary with couriers and payment providers to fulfil your order. We do not sell your personal information.</p><h2>Cookies</h2><p>We use essential cookies to keep your bag and session, and optional analytics cookies to improve the store.</p><h2>Contact</h2><p>For privacy requests, contact us via the <a href="/contact">contact page</a>.</p>' . $review, null],
    ['Terms & Conditions', 'terms-and-conditions', 'default', 'Terms that apply when you use this website and place orders.',
        '<h2>Orders</h2><p>All orders are subject to availability and confirmation. We may cancel orders affected by pricing errors or stock issues and will refund any payment received.</p><h2>Pricing</h2><p>Prices are in Pakistani Rupees and include applicable taxes unless stated otherwise. Delivery charges are shown at checkout.</p><h2>Payment</h2><p>We accept the payment methods shown at checkout. Cash on Delivery orders must be paid in full to the courier on delivery.</p><h2>Customised products</h2><p>Made-to-order and customised items are produced to your specifications and are not eligible for change-of-mind returns.</p>' . $review, null],
    ['FAQs', 'faqs', 'faq', 'Answers to common questions about orders, delivery and sizing.',
        '<h3>Do you offer Cash on Delivery?</h3><p>Yes, Cash on Delivery is available in most cities across Pakistan. Availability for your area is shown at checkout.</p><h3>How long does delivery take?</h3><p>Usually 1–5 working days depending on your city. The estimate for your address is shown at checkout.</p><h3>Can I exchange a size?</h3><p>Yes — unworn items with tags can be exchanged within 7 days of delivery. See our <a href="/returns-and-exchanges">Returns &amp; Exchanges</a> policy.</p><h3>Do I need an account to order?</h3><p>No. You can check out as a guest and optionally create an account to track orders more easily.</p><h3>How do I track my order?</h3><p>Use the <a href="/track-order">Track Order</a> page with your order number and email or phone number.</p><h3>Can I order a custom size?</h3><p>Selected products offer made-to-measure options. Look for the customisation fields on the product page.</p>', null],
    ['Delivery Information', 'delivery-information', 'default', 'How and when your order will reach you.',
        '<p>Orders placed before 2pm on working days are usually dispatched the same or next working day. Delivery estimates for your city are calculated at checkout. You will be notified when your order ships.</p><p>For made-to-order items, the production time shown on the product page is added to the delivery estimate.</p>' . $review, null],
    ['Payment Information', 'payment-information', 'default', 'Payment methods accepted at Urban Collections.',
        '<h2>Cash on Delivery</h2><p>Pay in cash to the courier when your order arrives.</p><h2>JazzCash &amp; Easypaisa</h2><p>Where enabled, pay securely on the JazzCash or Easypaisa payment page.</p><h2>Debit / credit cards</h2><p>Where enabled, card payments are processed on a secure hosted payment page. We never see or store your full card number or security code.</p><p>Only payment methods that are currently available are shown at checkout.</p>', null],
];
