        'seo_og_image' => 'assets/images/brand/og-default.jpg', 'seo_google_verification' => '', 'seo_bing_verification' => '', 'seo_noindex_site' => '0',
        'robots_txt' => "User-agent: *\nDisallow: /admin/\nDisallow: /ajax/\nDisallow: /api/\nDisallow: /cart\nDisallow: /checkout\nDisallow: /account/\nDisallow: /search\n",
        'ads_txt' => '', 'analytics_ga4_id' => '', 'analytics_gtm_id' => '', 'analytics_fb_pixel' => '', 'analytics_exclude_admins' => '1',
    ],
];
$sRows = [];
foreach ($settings as $group => $kv) {
    foreach ($kv as $k => $v) {
        $sRows[] = ['setting_key' => $k, 'setting_value' => $v, 'setting_group' => $group];
    }
}
$insert('site_settings', $sRows);

$out[] = 'SET FOREIGN_KEY_CHECKS = 1;';
file_put_contents($root . '/database/seed.sql', implode("\n\n", $out) . "\n");
file_put_contents($root . '/database/urban_collections.sql', file_get_contents($root . '/database/schema.sql') . "\n\n" . implode("\n\n", $out) . "\n");
echo 'Wrote database/seed.sql (' . count($products) . ' products, ' . count($variants) . " variants) and database/urban_collections.sql\n";
